package com.ecommerce.product.service;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="products",indexes={@Index(name="idx_product_vendor",columnList="vendor_id"),@Index(name="idx_product_sku",columnList="sku",unique=true)}) public class Product { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private UUID vendorId; @Column(nullable=false,length=120) private String name; @Column(nullable=false,length=120) private String category; @Column(nullable=false,unique=true,length=50) private String sku; @Column(length=2000) private String description; @Column(nullable=false,precision=14,scale=2) private BigDecimal price; @Column(nullable=false) private boolean active=true; private Instant createdAt=Instant.now(); public UUID getId(){return id;} public UUID getVendorId(){return vendorId;} public void setVendorId(UUID v){vendorId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getSku(){return sku;} public void setSku(String v){sku=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public Instant getCreatedAt(){return createdAt;} }